    try {
        GL11.glEnable(GL11.GL_CULL_FACE);
        switch(context.transform) {
        case FIRST_PERSON_LEFT_HAND:
        case FIRST_PERSON_RIGHT_HAND: setupFirstPerson(item); renderFirstPerson(item); break;
